(1354716, 172888, 27735, '<td valign="top">Very sharp, great colors, and perfect reflection. 9</td>', 'Very sharp, great colors, and perfect reflection. 9', '2005-05-03 02:15:59.000000', NULL, 1),
(1354718, 173028, 22479, '<td valign="top">Hey now, this would be a good entry for the Dreams challenge. It just doesn''t convey ecstasy to me. Yet it''s a great abstract.</td>', 'Hey now, this would be a good entry for the Dreams challenge. It just doesn''t convey ecstasy to me. Yet it''s a great abstract.', '2005-05-03 02:17:35.000000', NULL, 1),
