(1354725, 173058, 27735, '<td valign="top">Awesome color and focus on the eyes! 9</td>', 'Awesome color and focus on the eyes! 9', '2005-05-03 02:20:13.000000', NULL, 1),
(1354727, 170900, 22479, '<td valign="top">Wow if this isn''t "disturbed", nothing is! Just fantastically and deliciously gruesome. Masterful use of lighting to maximize the utilization of shadows. Intense. 10</td>', 'Wow if this isn''t "disturbed", nothing is! Just fantastically and deliciously gruesome. Masterful use of lighting to maximize the utilization of shadows. Intense. 10', '2005-05-03 02:21:12.000000', NULL, 1),
(1354728, 172748, 36299, '<td valign="top">Wonderful,  the texture o the photo is like velvet.  Only thing I would change is getting  the white light caught in the eyes. 9.</td>', 'Wonderful,  the texture o the photo is like velvet.  Only thing I would change is getting  the white light caught in the eyes. 9.', '2005-05-03 02:22:21.000000', NULL, 1),
(1354731, 172402, 27735, '<td valign="top">Great crop...excellent focus around the eyes. 9</td>', 'Great crop...excellent focus around the eyes. 9', '2005-05-03 02:23:15.000000', NULL, 1),
