(1363144, 172072, 36299, '<td valign="top">Great rendition of an event.  It is very clean and the detail is sharp. 10.</td>', 'Great rendition of an event.  It is very clean and the detail is sharp. 10.', '2005-05-05 12:49:08.000000', NULL, 1),
(1363147, 172846, 36299, '<td valign="top">I love the lighting in this and the focus of the veil and softness of the exposed face beyond the veil. 10</td>', 'I love the lighting in this and the focus of the veil and softness of the exposed face beyond the veil. 10', '2005-05-05 12:50:03.000000', NULL, 1),
