INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1364181, 172936, 16266, '<td valign="top">fun image, great lighting and contrast</td>', 'fun image, great lighting and contrast', '2005-05-05 18:17:53.000000', NULL, 1),
(1364281, 172846, 34759, '<td valign="top">This is one of my favorites in the group. Wonderful job!</td>', 'This is one of my favorites in the group. Wonderful job!', '2005-05-05 18:50:32.000000', NULL, 1),
(1364284, 172787, 34481, '<td valign="top">Great candid shot.  I love the symetry of the opposing faces.  Good luck</td>', 'Great candid shot.  I love the symetry of the opposing faces.  Good luck', '2005-05-05 18:51:10.000000', NULL, 1),
(1364286, 172931, 34759, '<td valign="top">I love this one. It really conveys a feeling without showing the expression on someone''s face. Great job.</td>', 'I love this one. It really conveys a feeling without showing the expression on someone''s face. Great job.', '2005-05-05 18:51:23.000000', NULL, 1),
(1364290, 172939, 34481, '<td valign="top">I think your score will improve is you submit a larger image.</td>', 'I think your score will improve is you submit a larger image.', '2005-05-05 18:52:05.000000', NULL, 1),
(1364293, 171447, 34481, '<td valign="top">very delicate portrait.  I''m sure it will do well in the challenge.</td>', 'very delicate portrait.  I''m sure it will do well in the challenge.', '2005-05-05 18:52:47.000000', NULL, 1),
(1364294, 172869, 34481, '<td valign="top">Great expression.  It might be improved by cropping out the blury foreground.</td>', 'Great expression.  It might be improved by cropping out the blury foreground.', '2005-05-05 18:53:36.000000', NULL, 1),
(1364296, 172972, 34481, '<td valign="top">Beautiful image.  Nice tonality.  I dont find it depressing though.</td>', 'Beautiful image.  Nice tonality.  I dont find it depressing though.', '2005-05-05 18:54:21.000000', NULL, 1),
(1364298, 171163, 34481, '<td valign="top">love the contrast between color and grey.  Nice composition</td>', 'love the contrast between color and grey.  Nice composition', '2005-05-05 18:55:20.000000', NULL, 1),
(1364302, 173051, 34481, '<td valign="top">Nice capture of true emotion.  Not sure what I think about the reflection.  Good luck.</td>', 'Nice capture of true emotion.  Not sure what I think about the reflection.  Good luck.', '2005-05-05 18:55:59.000000', NULL, 1),
(1364308, 172857, 34481, '<td valign="top">cute expression.  I think the color cast may be a bit off.  I like the reflection adn the far-off stare.  Good luck.</td>', 'cute expression.  I think the color cast may be a bit off.  I like the reflection adn the far-off stare.  Good luck.', '2005-05-05 18:58:23.000000', NULL, 1),
(1364311, 172899, 34481, '<td valign="top">One of my favorites of the challenge.  I which I could see more of the horses legs.  Maybe if you had laid on your belly you could have gotten more of the horse in the sky.  But hey, great capture.  Looks like my native Kentucky.</td>', 'One of my favorites of the challenge.  I which I could see more of the horses legs.  Maybe if you had laid on your belly you could have gotten more of the horse in the sky.  But hey, great capture.  Looks like my native Kentucky.', '2005-05-05 18:59:58.000000', NULL, 1),
(1364319, 171632, 34481, '<td valign="top">Wow!  That is scary looking.  One of my favorites though.  I''d be surprised if you don''t ribbon.  Good luck</td>', 'Wow!  That is scary looking.  One of my favorites though.  I''d be surprised if you don''t ribbon.  Good luck', '2005-05-05 19:00:59.000000', NULL, 1),
(1364323, 173066, 34481, '<td valign="top">Made me laugh out loud.  Great image.</td>', 'Made me laugh out loud.  Great image.', '2005-05-05 19:01:47.000000', NULL, 1),
(1364329, 172437, 34481, '<td valign="top">I''m sure it is peaceful for her, but if I was doing that I would be in great pain I am sure.  Good concept, but the angle is a little static, maybe experiment with same theme and different angles and lighting.  Maybe black and white.  Good luck.</td>', 'I''m sure it is peaceful for her, but if I was doing that I would be in great pain I am sure.  Good concept, but the angle is a little static, maybe experiment with same theme and different angles and lighting.  Maybe black and white.  Good luck.', '2005-05-05 19:03:56.000000', NULL, 1),
(1364333, 172679, 34481, '<td valign="top">Looks like fun.  Great timing with the spray.  Where is this?  I live in Bolivia and it looks like lots of places in the Andes.</td>', 'Looks like fun.  Great timing with the spray.  Where is this?  I live in Bolivia and it looks like lots of places in the Andes.', '2005-05-05 19:05:06.000000', NULL, 1),
(1364377, 171068, 34481, '<td valign="top">Great panning shot.  I love the crispness of the cyclist and the blur of the couple on the bench.  Good luck</td>', 'Great panning shot.  I love the crispness of the cyclist and the blur of the couple on the bench.  Good luck', '2005-05-05 19:18:23.000000', NULL, 1),
(1364382, 173016, 34481, '<td valign="top">Great capture.  I love the composition and the lighting.  It would be a stronger image if her face was in sharper focus.</td>', 'Great capture.  I love the composition and the lighting.  It would be a stronger image if her face was in sharper focus.', '2005-05-05 19:19:39.000000', NULL, 1),
(1364386, 173028, 34481, '<td valign="top">Nice abstract expression of an emotion.  Congrats on the originality.  Good luck.</td>', 'Nice abstract expression of an emotion.  Congrats on the originality.  Good luck.', '2005-05-05 19:20:28.000000', NULL, 1),
(1364394, 170900, 34481, '<td valign="top">Is the model or the photographer disturbed?  This image disturbs me.  Which is what it is meant to do I guess.  The eyes cut right through me.  I''m sure it will do well.</td>', 'Is the model or the photographer disturbed?  This image disturbs me.  Which is what it is meant to do I guess.  The eyes cut right through me.  I''m sure it will do well.', '2005-05-05 19:21:53.000000', NULL, 1),
(1364397, 172684, 34481, '<td valign="top">Great image.  I have seen that expression often.  You captured it perfectly.  Good luck.</td>', 'Great image.  I have seen that expression often.  You captured it perfectly.  Good luck.', '2005-05-05 19:22:35.000000', NULL, 1),
(1364398, 172864, 34481, '<td valign="top">Great capture and title.  You caught a sister''s frustration perfectly.  Good luck.</td>', 'Great capture and title.  You caught a sister''s frustration perfectly.  Good luck.', '2005-05-05 19:23:30.000000', NULL, 1),
(1364470, 172982, 32595, '<td valign="top">I like it ..took me awile....well hiddon, good idea and nice shot.</td>', 'I like it ..took me awile....well hiddon, good idea and nice shot.', '2005-05-05 19:53:29.000000', NULL, 1),
(1364474, 172141, 32595, '<td valign="top">Had to look that one up ...yes good capture on the mood and great tones</td>', 'Had to look that one up ...yes good capture on the mood and great tones', '2005-05-05 19:55:47.000000', NULL, 1),
