(1364484, 172829, 32595, '<td valign="top">Nice shot great color..........good capture of the mood</td>', 'Nice shot great color..........good capture of the mood', '2005-05-05 20:00:17.000000', NULL, 1),
(1364531, 173063, 18191, '<td valign="top">I like the soft violet colors here.</td>', 'I like the soft violet colors here.', '2005-05-05 20:18:36.000000', NULL, 1),
