(1371834, 172933, 8637, '<td valign="top">Cool reflection, maybe a little soft but like this one a lot.</td>', 'Cool reflection, maybe a little soft but like this one a lot.', '2005-05-08 21:42:05.000000', NULL, 1),
(1371835, 172972, 37529, '<td valign="top">I like this photo.  Hints of Ansel Adams.</td>', 'I like this photo.  Hints of Ansel Adams.', '2005-05-08 21:42:35.000000', NULL, 1),
(1371837, 173055, 37529, '<td valign="top">Super sunset/sunrise colors.  Leaves me with a relaxing and tranquil mood.</td>', 'Super sunset/sunrise colors.  Leaves me with a relaxing and tranquil mood.', '2005-05-08 21:45:23.000000', NULL, 1),
